<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useField, useForm } from 'vee-validate'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel, FieldSet, FieldLegend } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog'
import { Separator } from '@/components/ui/separator'
import { calculate, format, parseAmount } from './calculator'
import FinancialChart from '@/components/FinancialChart.vue'

const key='hesabro-vue-demo-v1', ttl=86400000
const services=[['print','پرینت','▤'],['scan','اسکن','▧'],['online','ثبت‌نام اینترنتی','⌘'],['typing','تایپ','✎'],['agency','پرداخت به نمایندگی','↗']] as const
const initial={step:0,visited:0,services:['print','online'],total:'100000',fee:'100000',expense:'25000',expenseEnabled:false,updated:Date.now(),version:1}
type Session=typeof initial
let storageAvailable=true
function restore():Session { try {const raw=localStorage.getItem(key);if(!raw)return {...initial,services:[...initial.services]};const s=JSON.parse(raw);if(s.version!==1||!Number.isFinite(s.updated)||Date.now()-s.updated>ttl||!Number.isInteger(s.step)||s.step<0||s.step>6||!Number.isInteger(s.visited)||s.visited<s.step||s.visited>6||!Array.isArray(s.services)||!s.services.every((x:string)=>services.some(v=>v[0]===x))||!['total','fee','expense'].every(x=>typeof s[x]==='string'&&s[x].length<30)||typeof s.expenseEnabled!=='boolean')throw Error();return s}catch{return {...initial,services:[...initial.services]}} }
const saved=restore(), step=ref(saved.step), visited=ref(saved.visited), selected=ref<string[]>(saved.services), expenseEnabled=ref(saved.expenseEnabled)
const agency=computed(()=>selected.value.includes('agency'))
useForm({initialValues:{total:saved.total,fee:saved.fee,expense:saved.expense}})
const {value:total}=useField<string>('total'), {value:fee}=useField<string>('fee'), {value:expense}=useField<string>('expense')
const totalError=computed(()=>parseAmount(total.value)===null?'مبلغ صحیح بین صفر تا ۱۰٬۰۰۰٬۰۰۰ تومان وارد کن.':'')
const feeError=computed(()=>parseAmount(fee.value)===null?'مبلغ صحیح وارد کن.':(parseAmount(total.value)!==null&&parseAmount(fee.value)!>parseAmount(total.value)!)?'حق‌الزحمه نمی‌تونه از کل دریافتی بیشتر باشه.':'')
const expenseError=computed(()=>parseAmount(expense.value)===null?'مبلغ صحیح بین صفر تا ۱۰٬۰۰۰٬۰۰۰ تومان وارد کن.':'')
const result=computed(()=>calculate(agency.value,total.value,fee.value,expenseEnabled.value?expense.value:'0'))
const valid=computed(()=>step.value===1?selected.value.length>0:step.value===3?!totalError.value&&(!agency.value||!feeError.value):step.value===4?!expenseEnabled.value||!expenseError.value:true)
const labels=['شروع تجربه','بریم سراغ دریافت','دریافت رو بررسی کن','ادامه','گزارش رو ببین','ادامه در حسابرو','ساخت دفتر واقعی']
const activation=ref(false), resetOpen=ref(false), branchOpen=ref(false), pending=ref<string[]>([]), note=ref(''), title=ref<HTMLElement|null>(null)
function save(){try{localStorage.setItem(key,JSON.stringify({step:step.value,visited:visited.value,services:selected.value,total:total.value,fee:fee.value,expense:expense.value,expenseEnabled:expenseEnabled.value,updated:Date.now(),version:1}))}catch{storageAvailable=false}}
watch([step,visited,selected,total,fee,expense,expenseEnabled],save,{deep:true})
function navigate(n:number,push=true){if(n<0||n>6)return;step.value=n;visited.value=Math.max(visited.value,n);note.value='';if(push)history.pushState({step:n},'');nextTick(()=>title.value?.focus())}
function changeChartExpense(value:number){ expense.value=String(value); expenseEnabled.value=true }
function next(){if(!valid.value)return;if(step.value===6){activation.value=true;return}navigate(step.value+1)}
function updateServices(v:unknown){const next=Array.isArray(v)?v.filter((x):x is string=>typeof x==='string'):[];if(next.includes('agency')!==agency.value){pending.value=next;branchOpen.value=true}else selected.value=next}
function applyBranch(){selected.value=pending.value;total.value=agency.value?'300000':'100000';fee.value=agency.value?'80000':'100000';expense.value='25000';expenseEnabled.value=false;note.value='نوع مثال تغییر کرد و مبالغ وابسته به مقدار اولیه برگشتند.'}
function reset(){selected.value=['print','online'];total.value='100000';fee.value='100000';expense.value='25000';expenseEnabled.value=false;visited.value=0;activation.value=false;navigate(0,false);history.replaceState({step:0},'');note.value='داده نمونه پاک شد و تجربه از ابتدا شروع شد.'}
onMounted(()=>{history.replaceState({step:step.value},'');window.addEventListener('popstate',e=>navigate(Number.isInteger(e.state?.step)&&e.state.step<=visited.value?e.state.step:0,false))})
let touch:{x:number,y:number}|null=null
function touchStart(e:TouchEvent){const t=e.touches[0];if(t)touch={x:t.clientX,y:t.clientY}}
function touchEnd(e:TouchEvent){const t=e.changedTouches[0];if(!touch||!t)return;const dx=t.clientX-touch.x,dy=t.clientY-touch.y;touch=null;if(Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.5)return;if(dx<0&&valid.value&&step.value<6)next();else if(dx>0&&step.value>0)navigate(step.value-1)}
</script>
<template>
 <main class="stage" dir="rtl"><aside class="desktop-note"><span class="brand-mark">✳</span><b>حسابرو وان</b><p>برای حساب‌وکتاب<br>روشن‌ترِ کسب‌وکار</p><span class="side-line"></span><small>یک تجربه تعاملی برای کافی‌نت‌ها</small></aside>
 <section class="story-shell" aria-label="تجربه تعاملی کافی‌نت"><header class="shell-header"><div class="progress" role="progressbar" aria-label="پیشرفت تجربه؛ از دکمه‌ها یا کشیدن این ناحیه استفاده کن" :aria-valuenow="step+1" aria-valuemin="1" aria-valuemax="7" @touchstart.passive="touchStart" @touchend.passive="touchEnd"><span v-for="i in 7" :key="i" :class="{active:i<=step+1}" /></div><div class="topline"><div class="brand"><span class="brand-mark">✳</span><b>حسابرو <small>وان</small></b></div><div class="header-actions"><span>{{ format(step+1) }} / {{ format(7) }}</span><Button variant="ghost" size="icon" aria-label="شروع دوباره و حذف داده نمونه" @click="resetOpen=true">↻</Button></div></div></header>
 <div class="story-scroll"><div class="content"><Alert v-if="note || !storageAvailable"><AlertDescription>{{ note || 'ذخیره روی این دستگاه در دسترس نیست.' }}</AlertDescription></Alert>
 <template v-if="step===0"><div class="eyebrow">● یک تجربه کوتاه برای کافی‌نت‌ها</div><h1 ref="title" tabindex="-1">همه پولی که می‌گیری،<br><em>درآمد خودته؟</em></h1><p class="lead">بیا با هم یک دریافت نمونه رو بررسی کنیم و ببینیم چه چیزی ازش برای کسب‌وکارت می‌مونه.</p><div class="hero-art"><div class="art-circle"></div><Card class="receipt"><CardHeader><CardTitle>رسید خدمات <span>✳</span></CardTitle><CardDescription>یک روز کاری نمونه</CardDescription></CardHeader><CardContent><div class="receipt-row"><span>دریافتی مشتری</span><b>••••••</b></div><Separator /><div class="receipt-row"><span>حق‌الزحمه شما</span><b>••••</b></div></CardContent><CardFooter>یک نگاه تازه به دخل‌وخرج</CardFooter></Card></div><p class="trust">✓ بدون نیاز به شماره موبایل · چند قدم ساده</p></template>
 <template v-else-if="step===1"><div class="eyebrow">اول از همه، کار تو</div><h1 ref="title" tabindex="-1">امروز چه کارهایی<br><em>انجام دادی؟</em></h1><p class="lead">یک یا چند خدمت رو انتخاب کن تا مثال رو با هم مرور کنیم.</p><FieldSet class="mt-6"><FieldLegend>خدمات نمونه</FieldLegend><ToggleGroup type="multiple" :model-value="selected" variant="outline" orientation="vertical" :spacing="2" class="service-group" aria-label="انتخاب خدمات" @update:model-value="updateServices"><ToggleGroupItem v-for="s in services" :key="s[0]" :value="s[0]" class="service-item"><span class="service-icon">{{ s[2] }}</span><span>{{ s[1] }}</span></ToggleGroupItem></ToggleGroup></FieldSet><p class="helper">{{ selected.length?'انتخاب‌هات رو هر وقت بخوای می‌تونی تغییر بدی.':'حداقل یک خدمت انتخاب کن.' }}</p></template>
 <template v-else-if="step===2"><Badge variant="secondary">✳ مثال فرضی</Badge><div class="eyebrow">یک لحظه از روز کاری</div><h1 ref="title" tabindex="-1">یک مشتری پرداخت کرد.<br><em>بیایم رسیدش رو ببینیم.</em></h1><p class="lead">{{ agency?'در این مثال فرض می‌کنیم بخشی از مبلغ به نمایندگی برای طرف دیگری دریافت شده.':'در این مثال ساده، همه دریافتی را مبلغ خدمت در نظر می‌گیریم.' }}</p><Card class="full-receipt"><CardHeader><CardTitle>رسید خدمات کافی‌نت</CardTitle><CardDescription>نمونه آموزشی</CardDescription></CardHeader><CardContent><div class="receipt-row"><span>نوع مثال</span><b>{{ agency?'پرداخت به نمایندگی':'خدمت معمولی' }}</b></div><Separator /><div class="receipt-row"><span>دریافتی مشتری</span><b>{{ parseAmount(total)===null?'—':format(parseAmount(total)!) }} تومان</b></div></CardContent><CardFooter>هیچ سند یا تراکنشی ثبت نمی‌شود.</CardFooter></Card></template>
 <template v-else-if="step===3"><Badge variant="secondary">✳ مثال فرضی</Badge><div class="eyebrow">حالا خودت امتحان کن</div><h1 ref="title" tabindex="-1">{{ agency?'چقدرش حق‌الزحمه':'دریافتی این خدمت' }}<br><em>{{ agency?'خودته؟':'چقدر بود؟' }}</em></h1><p class="lead">{{ agency?'عددها رو تغییر بده تا تفکیک این دریافت فرضی رو ببینی.':'برای این خدمت فرضی، کل دریافتی را مبلغ خدمت در نظر می‌گیریم.' }}</p><FieldGroup class="form-fields"><Field :data-invalid="!!totalError"><FieldLabel for="total">کل دریافتی از مشتری · تومان</FieldLabel><Input id="total" v-model="total" inputmode="numeric" :aria-invalid="!!totalError" :aria-describedby="totalError ? 'total-description total-error' : 'total-description'" /><FieldDescription id="total-description">عدد صحیح از صفر تا ۱۰٬۰۰۰٬۰۰۰ تومان</FieldDescription><FieldError v-if="totalError" id="total-error">{{ totalError }}</FieldError></Field><Field v-if="agency" :data-invalid="!!feeError"><FieldLabel for="fee">حق‌الزحمه خدمت · تومان</FieldLabel><Input id="fee" v-model="fee" inputmode="numeric" :aria-invalid="!!feeError" :aria-describedby="feeError ? 'fee-description fee-error' : 'fee-description'" /><FieldDescription id="fee-description">نباید از کل دریافتی بیشتر باشد.</FieldDescription><FieldError v-if="feeError" id="fee-error">{{ feeError }}</FieldError></Field></FieldGroup><Card class="live-card"><CardHeader><CardDescription>{{ agency?'وجه عبوری فرضی':'حق‌الزحمه فرضی' }}</CardDescription><CardTitle>{{ !totalError && (!agency || !feeError) ? format(agency?parseAmount(total)!-parseAmount(fee)!:parseAmount(total)!)+' تومان':'—' }}</CardTitle></CardHeader><CardFooter>{{ agency?'با فرض دریافت به نمایندگی برای طرف ثالث':'در این مثال وجه عبوری وجود ندارد' }}</CardFooter></Card></template>
 <template v-else-if="step===4"><Badge variant="secondary">✳ مثال فرضی</Badge><div class="eyebrow">یک قدم تا گزارش</div><h1 ref="title" tabindex="-1">هزینه‌های انجام کار<br><em>چقدر شد؟</em></h1><p class="lead">فقط هزینه مرتبط با همین خدمت نمونه رو در نظر بگیر؛ اضافه کردن هزینه اختیاریه.</p><Button variant="outline" class="expense-toggle" :aria-pressed="expenseEnabled" @click="expenseEnabled=!expenseEnabled">{{ expenseEnabled?'✓':'+' }} &nbsp; {{ agency?'اینترنت یا اپراتور':'کاغذ و تونر' }}</Button><FieldGroup v-if="expenseEnabled" class="form-fields"><Field :data-invalid="!!expenseError"><FieldLabel for="expense">مبلغ هزینه نمونه · تومان</FieldLabel><Input id="expense" v-model="expense" inputmode="numeric" :aria-invalid="!!expenseError" :aria-describedby="expenseError ? 'expense-error' : undefined" /><FieldError v-if="expenseError" id="expense-error">{{ expenseError }}</FieldError></Field></FieldGroup><p v-else class="helper">اگر هزینه‌ای اضافه نکنی، در گزارش صفر در نظر گرفته می‌شود.</p><Alert class="note"><AlertTitle>هزینه مرتبط با مثال</AlertTitle><AlertDescription>هزینه ماهانه بدون مبنای تخصیص به این خدمت اضافه نمی‌شود.</AlertDescription></Alert></template>
 <template v-else-if="step===5 && result"><Badge variant="secondary">✳ مثال فرضی</Badge><div class="eyebrow">تصویر روشن‌تر</div><h1 ref="title" tabindex="-1">{{ agency?'دریافتی با درآمد':'درآمد و هزینه رو' }}<br><em>{{ agency?'یکی نیست.':'جدا ببین.' }}</em></h1><p class="lead">این نتیجه فقط بر اساس عددهای همین مثال آموزشی است.</p><Card class="result-card"><CardHeader><CardDescription>مازاد پس از هزینه‌های واردشده</CardDescription><CardTitle>{{ format(result.surplus) }} تومان</CardTitle></CardHeader><CardFooter>{{ result.surplus<0?'مازاد منفی است؛ هزینه‌های انتخابی از حق‌الزحمه بیشترند.':'بر اساس هزینه‌های انتخابی، نه سود خالص قطعی' }}</CardFooter></Card><FinancialChart :agency="agency" :received="result.received" :fee="result.serviceFee" :pass-through="result.passThrough" :expense="result.cost" @change-expense="changeChartExpense" /><div class="breakdown"><div><span>دریافتی مشتری</span><b>{{ format(result.received) }} تومان</b></div><div><span>حق‌الزحمه خدمت</span><b>{{ format(result.serviceFee) }} تومان</b></div><div v-if="agency"><span>وجه عبوری فرضی</span><b>{{ format(result.passThrough) }} تومان</b></div><div><span>هزینه‌های انتخابی</span><b>{{ format(result.cost) }} تومان</b></div></div><details><summary>این عدد چطور حساب شد؟</summary><p>حق‌الزحمه منهای هزینه‌های واردشده، مازاد آموزشی است. {{ agency?'وجه عبوری با فرض رابطه نمایندگی برابر دریافتی منهای حق‌الزحمه است.':'' }} این مثال گزارش حسابداری یا محاسبه مالیات نیست.</p></details><Alert class="note"><AlertTitle>حسابرو چطور کمک می‌کنه؟</AlertTitle><AlertDescription>ثبت درآمد و هزینه، دریافت و پرداخت و گردش حساب در مستندات محصول آمده است. تفکیک وجه عبوری در اینجا فقط یک سناریوی آموزشی است.</AlertDescription></Alert></template>
 <template v-else-if="step===6"><div class="activation-symbol">✳</div><div class="eyebrow">این تازه شروع راهه</div><h1 ref="title" tabindex="-1">حالا نوبت<br><em>کافی‌نت خودته.</em></h1><p class="lead">با اطلاعات واقعی کسب‌وکارت ادامه بده و ثبت‌های خودت رو در یک دفتر منظم نگه دار.</p><Card class="activation-card"><CardHeader><CardTitle>مسیر ادامه</CardTitle><CardDescription>از مثال تا دفتر واقعی</CardDescription></CardHeader><CardContent><ol><li>ورود و تأیید شماره موبایل</li><li>انتخاب یا ساخت دفتر کسب‌وکار</li><li>ثبت اولین عملیات مالی واقعی</li></ol></CardContent><CardFooter>داده‌های این مثال به دفتر واقعی منتقل نمی‌شوند.</CardFooter></Card><Alert v-if="activation" class="note" role="status"><AlertTitle>اتصال هنوز آماده نیست</AlertTitle><AlertDescription>هیچ حساب یا دفتری ساخته نشده است.</AlertDescription></Alert></template>
 <template v-else><h1 ref="title" tabindex="-1">اطلاعات مثال کامل نیست</h1><p>به مرحله قبل برگرد و مبلغ‌ها رو بررسی کن.</p></template>
 </div></div><footer class="shell-footer"><Button v-if="step>0" variant="outline" size="icon" aria-label="مرحله قبل" @click="navigate(step-1)">→</Button><Button class="next-button" :disabled="!valid" @click="next">{{ labels[step] }} <span aria-hidden="true">←</span></Button><p>{{ step===1&&!valid?'حداقل یک خدمت انتخاب کن.':step===0?'یک مثال آموزشی، بدون ثبت اطلاعات واقعی':'اطلاعات این تجربه فقط روی همین دستگاه می‌ماند' }}</p></footer></section>
 <AlertDialog v-model:open="resetOpen"><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>شروع دوباره تجربه؟</AlertDialogTitle><AlertDialogDescription>اطلاعات نمونه از این دستگاه پاک می‌شود.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>انصراف</AlertDialogCancel><AlertDialogAction @click="reset">شروع دوباره</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 <AlertDialog v-model:open="branchOpen"><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>نوع مثال تغییر کند؟</AlertDialogTitle><AlertDialogDescription>با تغییر نوع خدمت، مبلغ‌ها و هزینه نمونه به مقدار اولیه برمی‌گردند.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>انصراف</AlertDialogCancel><AlertDialogAction @click="applyBranch">تغییر مثال</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></main>
</template>
